codeExamples.code:
USE CATALOG sales_catalog;
USE SCHEMA gold;

-- Managed table: no LOCATION, stored under the schema's managed location
CREATE TABLE orders (
  order_id   BIGINT,
  customer_id BIGINT,
  amount     DECIMAL(10,2),
  order_ts   TIMESTAMP
)
USING DELTA
TBLPROPERTIES ('delta.enableChangeDataFeed' = 'true');

-- External table: files already exist at a path under an external location
CREATE TABLE partner_orders (
  order_id BIGINT,
  amount   DECIMAL(10,2)
)
USING DELTA
LOCATION 's3://partner-bucket/shared/orders';

DESCRIBE EXTENDED orders;

-- Traversal privileges on the parents are required first
GRANT USE CATALOG ON CATALOG sales_catalog TO `analysts`;
GRANT USE SCHEMA  ON SCHEMA  sales_catalog.gold TO `analysts`;

-- Read access to a specific table
GRANT SELECT ON TABLE sales_catalog.gold.orders TO `analysts`;

-- Write access for the engineering team
GRANT SELECT, MODIFY ON TABLE sales_catalog.gold.orders TO `data_eng`;

-- Remove read access from analysts
REVOKE SELECT ON TABLE sales_catalog.gold.orders FROM `analysts`;

-- Transfer ownership to a group (owner has full control)
ALTER TABLE sales_catalog.gold.orders OWNER TO `data_eng`;

SHOW GRANTS ON TABLE sales_catalog.gold.orders;

-- Managed table: DROP removes metadata AND deletes the data files
DROP TABLE sales_catalog.gold.orders;

-- Recover it within the retention window (managed tables only)
UNDROP TABLE sales_catalog.gold.orders;

-- External table: DROP removes ONLY the metadata; files remain
DROP TABLE sales_catalog.bronze.partner_orders;

-- The partner files still exist; re-register without copying data
CREATE TABLE sales_catalog.bronze.partner_orders (
  order_id BIGINT,
  amount   DECIMAL(10,2)
)
USING DELTA
LOCATION 's3://partner-bucket/shared/orders';
